#!/bin/bash
# fix_db_names.sh
# Fixes FASTA naming inconsistencies in STRspy2.0-DB generated by BuildDB_From_GeneBank.V1.sh
# BuildDB writes some loci as <locus>mod.fa or <locus>mod1.fa, but STRspy looks for <locus>.fa.
#
# For every locus that has *mod*.fa files, this script merges <locus>.fa (if it exists) with all
# <locus>mod*.fa files into a single <locus>.fa, keeping the first copy of each record header.
# Nothing is lost when both files exist (e.g. DYS385ab, DYS390, DYS458), and loci that only
# have a mod file (e.g. TPOX, FGA) get their <locus>.fa created.
# If the same header appears with a different sequence, the first one is kept and a warning is printed.
# The *mod*.fa files are not modified or removed, so the script is safe to run more than once.
# The .fai index of each merged FASTA is regenerated if samtools is available.
# The DB directory must be writable: unzipping the prebuilt STRspy2.0-DB.zip leaves it read-only,
# so run chmod u+w on it first (the script stops with a message if it is not writable).
#
# Usage: bash fix_db_names.sh <path_to_DB_dir>
# Author: Tamara Frontanilla Recalde (fix) | Original: Kesharwani RK

set -uo pipefail
shopt -s nullglob

DB_DIR=${1:-"."}

if [[ ! -d "$DB_DIR" ]]; then
  echo "Error: Directory $DB_DIR not found"
  echo "Usage: bash fix_db_names.sh <path_to_DB_dir>"
  exit 1
fi

cd "$DB_DIR" || exit 1
echo "Fixing FASTA names in: $(pwd)"

count_records() {
  awk '/^>/ { n++ } END { print n + 0 }' "$1"
}

# Collect the locus names that have at least one <locus>mod.fa or <locus>mod1.fa file
re='^(.+)mod[0-9]*\.fa$'
loci=()
while IFS= read -r l; do
  loci+=("$l")
done < <(
  for f in *mod*.fa; do
    if [[ "$f" =~ $re ]]; then
      echo "${BASH_REMATCH[1]}"
    fi
  done | sort -u
)

if [[ ${#loci[@]} -eq 0 ]]; then
  echo "No *mod*.fa files found. Nothing to do."
  exit 0
fi

# The merged files are written next to the originals, so the directory itself must be writable
if [[ ! -w . ]]; then
  echo "Error: $(pwd) is not writable, so the merged FASTAs cannot be written."
  echo "The prebuilt STRspy2.0-DB.zip unzips to a read-only folder. Make it writable and run again:"
  echo "      chmod u+w \"$(pwd)\""
  exit 1
fi

processed=0
errors=0
have_samtools=0
if command -v samtools >/dev/null 2>&1; then
  have_samtools=1
fi

for locus in "${loci[@]}"; do
  sources=()
  before=0
  if [[ -f "$locus.fa" ]]; then
    sources+=("$locus.fa")
    before=$(count_records "$locus.fa")
  fi
  sources+=("${locus}"mod*.fa)

  echo "Merging for $locus: ${sources[*]}"

  # Merge all records, dropping repeated headers (first copy wins)
  if awk -v locus="$locus" '
    function emit() {
      if (hdr == "") return
      if (hdr in seen) {
        if (seen[hdr] != seq) conflicts++
      } else {
        seen[hdr] = seq
        printf "%s", rec
      }
    }
    /^>/ { emit(); hdr = $1; rec = $0 ORS; seq = ""; next }
    { rec = rec $0 ORS; seq = seq $0 }
    END {
      emit()
      if (conflicts > 0)
        printf "  WARNING: %s has %d header(s) repeated with a different sequence (kept the first one)\n", locus, conflicts > "/dev/stderr"
    }
  ' "${sources[@]}" > "$locus.fa.tmp"; then
    mv "$locus.fa.tmp" "$locus.fa"
  else
    rm -f "$locus.fa.tmp"
    echo "  ERROR: could not merge files for $locus, left unchanged"
    errors=$((errors + 1))
    continue
  fi

  after=$(count_records "$locus.fa")
  printf '  %-12s %4d -> %4d records (+%d)\n' "$locus" "$before" "$after" "$((after - before))"

  if [[ $have_samtools -eq 1 ]]; then
    samtools faidx "$locus.fa"
  fi
  processed=$((processed + 1))
done

echo "Done. $processed locus/loci merged, $errors error(s)."

if [[ $have_samtools -eq 0 ]]; then
  echo "NOTE: samtools not found. Regenerate the indexes before running STRspy:"
  echo "      for f in *.fa; do samtools faidx \"\$f\"; done"
fi

exit $((errors > 0))
